const now = new Date();
const stoppedStatuses = new Set(["BOOKED", "CLOSED", "HUMAN_TAKEOVER"]);
const maxFollowUps = 3;

function normalize(value) {
  return String(value || "").trim().toUpperCase();
}

return items
  .map((item) => {
    const lead = item.json;
    const nextFollowUpAt = lead.next_follow_up_at ? new Date(lead.next_follow_up_at) : null;
    const followUpCount = Number(lead.follow_up_count || 0);
    const consentStatus = normalize(lead.consent_status || "UNKNOWN");
    const leadStatus = normalize(lead.lead_status);

    const blockReasons = [];

    if (!nextFollowUpAt || Number.isNaN(nextFollowUpAt.getTime())) {
      blockReasons.push("missing_next_follow_up_at");
    } else if (nextFollowUpAt > now) {
      blockReasons.push("not_due_yet");
    }

    if (consentStatus === "OPTED_OUT") {
      blockReasons.push("consent_opted_out");
    }

    if (stoppedStatuses.has(leadStatus)) {
      blockReasons.push(`lead_status_${leadStatus.toLowerCase()}`);
    }

    if (lead.human_takeover === true) {
      blockReasons.push("human_takeover");
    }

    if (followUpCount >= maxFollowUps) {
      blockReasons.push("max_follow_ups_reached");
    }

    return {
      json: {
        ...lead,
        consent_status: ["OPTED_IN", "OPTED_OUT"].includes(consentStatus) ? consentStatus : "UNKNOWN",
        follow_up_count: followUpCount,
        automation_can_continue: blockReasons.length === 0,
        automation_block_reasons: blockReasons,
        evaluated_at: now.toISOString(),
      },
    };
  })
  .filter((item) => item.json.automation_can_continue);

const now = new Date();

function addDays(days) {
  return new Date(now.getTime() + days * 24 * 60 * 60 * 1000).toISOString();
}

return items.map((item) => {
  const lead = item.json;
  const nextCount = Number(lead.follow_up_count || 0) + 1;
  const isFinalAttempt = nextCount >= 3;
  const nextFollowUpAt = isFinalAttempt ? null : addDays(nextCount === 1 ? 5 : 7);
  const followUpStatus = isFinalAttempt ? "COMPLETE" : "ACTIVE";

  const customerName = lead.name && lead.name !== "Unknown" ? lead.name : "there";
  const message = [
    `Hi ${customerName}, thanks again for your solar enquiry.`,
    "Would you like help comparing a solar-and-backup option for your home?",
    "Reply STOP if you do not want further follow-up.",
  ].join(" ");

  return {
    json: {
      ...lead,
      follow_up_count: nextCount,
      follow_up_status: followUpStatus,
      last_follow_up_at: now.toISOString(),
      next_follow_up_at: nextFollowUpAt,
      nurture_message: message,
      nurture_delivery_status: "READY_TO_SEND",
    },
  };
});

