const lead = $("Prepare WARM Follow-up").item.json;
const gmailResult = $json;

function getErrorMessage(result) {
  if (!result || !result.error) {
    return null;
  }

  if (typeof result.error === "string") {
    return result.error;
  }

  return result.error.message || result.error.description || JSON.stringify(result.error);
}

const errorMessage = getErrorMessage(gmailResult);

return [
  {
    json: {
      ...lead,
      gmail_notification_result: gmailResult,
      nurture_delivery_status: errorMessage ? "FAILED" : "SENT",
      nurture_delivery_error: errorMessage,
    },
  },
];
